parameters.jsCode:
// Kampagnen (ALLY 26, BA6, Stefan 20.10.2026, Entwurf Kampagne.dc.html): Liste (Überblick, Alle Kampagnen, Nächste Deadlines, Freigaben), Kampagne (Überblick mit Offen
// und Zielen, Briefing, Talents und Deliverables, Zeitplan, Erinnerungen, Freigaben, Reporting) und Beiträge zuordnen. Daten aus talents_kampagnen_ui, talents_kampagne_ui,
// talents_ui_kampagne_zuordnen (Migration 61; Rollen nach Stefan 20.10.2026). Aktionen tk_* (wie ALLY 8) und kp_* (Kampagnenplanung). Links zu Cloud-Diensten nur über die interne Seite „link“
// (ALLY 20 leitet nach Prüfung in der Datenbank weiter). Liefert nur die Seitenbeschreibung (JSON).
const E = $('Start').first().json;
const D = $input.first().json || {};
const P = E.parameter || {};
const krumen0 = [{ text: 'Startseite', ziel: { seite: 'start' } }, { text: 'Kampagnen', ziel: { seite: 'kampagnen' } }];
const zahnrad = { ziel: { seite: 'einstellungen', parameter: { bereich: 'kampagnen' } }, label: 'Einstellungen für Kampagnen' };
const aus = inhalt => [{ json: { inhalt } }];
const fehlt = (titel, text, zurueck) => aus({ seite: { schluessel: 'kampagnen', art: 'funktion', titel, krumen: krumen0.concat([{ text: titel }]) },
  bloecke: [{ typ: 'hinweis', ton: 'warn', text: String(text || 'Diese Seite ist für dich nicht freigeschaltet.') }, { typ: 'aktion', text: zurueck ? 'Zu den Kampagnen' : 'Zur Startseite', ziel: { seite: zurueck ? 'kampagnen' : 'start' } }] });
if (D.ok !== true) return fehlt('Kampagnen', 'Bitte neu anmelden.');
const PLATT = [['instagram', 'Instagram'], ['tiktok', 'TikTok'], ['youtube', 'YouTube'], ['facebook', 'Facebook'], ['threads', 'Threads'], ['pinterest', 'Pinterest'], ['linkedin', 'LinkedIn'], ['sonstige', 'Sonstige']];
const FORM = [['reel', 'Reel'], ['post', 'Post'], ['karussell', 'Karussell'], ['story', 'Story'], ['video', 'Video'], ['short', 'Short'], ['live', 'Live'], ['sonstiges', 'Sonstiges']];
const STATI = [['geplant', 'geplant'], ['entwurf', 'Entwurf'], ['pruefung', 'Freigabe intern'], ['ueberarbeiten', 'Überarbeiten'], ['bei_marke', 'Freigabe Marke'], ['freigegeben', 'freigegeben'], ['veroeffentlicht', 'veröffentlicht'], ['abgerechnet', 'abgerechnet']];
const opt = (l, leer) => (leer ? [{ wert: '', text: leer }] : []).concat(l.map(x => ({ wert: x[0], text: x[1] })));
const tonStatus = s => ['veroeffentlicht', 'abgerechnet', 'freigegeben'].includes(s) ? 'ok' : s === 'ueberarbeiten' ? 'warn' : s === 'geplant' ? 'grau' : '';
const knoepfe = t => [{ text: 'Abbrechen', art: 'neben', schliesst: true }, { text: t || 'Speichern' }];
const zahl = (n, eins, viele) => n + ' ' + (n === 1 ? eins : viele);

// =====================================================================================================================
// Liste
// =====================================================================================================================
if (D.ansicht === 'liste') {
  const L = D.l || {};
  if (L.ok !== true) return fehlt('Kampagnen', L.fehler);
  const KZ = L.kennzahlen || {};
  const hier = (extra, anker) => ({ seite: 'kampagnen', parameter: Object.assign({}, P.status ? { status: P.status } : {}, P.suche ? { suche: P.suche } : {}, P.talent ? { talent: P.talent } : {}, extra || {}), anker });
  const zuK = (id, anker, extra) => ({ seite: 'kampagnen', parameter: Object.assign({ kampagne: id }, extra || {}), anker });
  const seite = { schluessel: 'kampagnen', art: 'funktion', titel: 'Kampagnen', beschreibung: 'Planung, Deliverables, Freigaben und Erinnerungen je Marke.',
    krumen: krumen0.slice(0, 1).concat([{ text: 'Kampagnen' }]), zahnrad };
  if (L.darf_anlegen) seite.hauptaktion = { text: 'Neue Kampagne', fenster: 'neu' };
  seite.aktionen = [{ text: 'Dashboard', ziel: { seite: 'talents' } }, { text: 'Reports', ziel: { seite: 'talent-reports' } }]
    .concat(L.darf_regeln ? [{ text: 'Standard-Erinnerungen', ziel: zahnrad.ziel }] : []);
  const ueberblick = { kennzahlen: [
    { label: 'Laufende Kampagnen', wert: String(KZ.laufend ?? 0), neben: KZ.geplant ? KZ.geplant + ' geplant' : '', ziel: hier({ status: 'laufend' }, 'a-alle') },
    { label: 'Offene Deliverables', wert: String(KZ.deliverables_offen ?? 0), neben: '' },
    { label: 'Deadlines 7 Tage', wert: String(KZ.deadlines_7 ?? 0), neben: KZ.ueberfaellig ? KZ.ueberfaellig + ' überfällig' : '', ton: KZ.ueberfaellig ? 'warn' : '', ziel: { seite: 'kampagnen', anker: 'a-naechste' } },
    { label: 'Freigaben offen', wert: String(KZ.freigaben_offen ?? 0), neben: '', ziel: { seite: 'kampagnen', anker: 'a-freigaben' } }],
    karten: [
      { titel: 'Offen', leer: 'Nichts offen.', eintraege: (L.offen || []).map(o => ({ marke: { text: String(o.marke || ''), ton: o.art === 'ueberfaellig' ? 'warn' : '' }, text: String(o.text || ''),
        ziel: o.art === 'freigabe' ? zuK(o.kampagne_id, 'a-freigaben', { f: 'v-' + o.version_id }) : zuK(o.kampagne_id, 'a-deliverables'), ziel_text: o.art === 'freigabe' ? 'Prüfen' : 'Öffnen' })) },
      { titel: 'Meldungen', leer: 'Keine neuen Meldungen.', eintraege: (L.meldungen || []).map(o => ({ marke: { text: String(o.marke || ''), ton: 'grau' }, text: String(o.text || ''),
        ziel: o.kampagne_id ? zuK(o.kampagne_id) : { seite: 'talent', parameter: { id: o.talent_id } }, ziel_text: 'Öffnen' })) }] };
  const F = L.filter || {};
  const filter = { typ: 'filter', id: 'alle', label: 'Kampagnen filtern', felder: [
    { typ: 'suche', name: 'suche', label: 'Suche', platzhalter: 'Marke oder Kampagne', wert: String(F.suche || '') },
    { typ: 'auswahl', name: 'status', label: 'Status', wert: String(F.status || ''), optionen: opt([['laufend', 'Laufend'], ['geplant', 'Geplant'], ['beendet', 'Beendet'], ['abgebrochen', 'Abgebrochen']], 'Alle') },
    { typ: 'auswahl', name: 'talent', label: 'Talent', wert: String(F.talent || ''), optionen: [{ wert: '', text: 'Alle Talents' }].concat((L.talent_auswahl || []).map(t => ({ wert: String(t.id), text: String(t.anzeigename || '') }))) }] };
  const mitBudget = L.darf_budget === true || (L.zeilen || []).some(z => z.budget_text);
  const spalten = [{ schluessel: 'kampagne', titel: 'Kampagne', sortierbar: true }, { schluessel: 'zeitraum', titel: 'Zeitraum', sortierbar: true },
    { schluessel: 'status', titel: 'Status', sortierbar: true }, { schluessel: 'talents', titel: 'Talents', sortierbar: true, ausrichtung: 'rechts' },
    { schluessel: 'deliverables', titel: 'Deliverables', sortierbar: true, ausrichtung: 'rechts' }, { schluessel: 'naechste', titel: 'Nächste Deadline', sortierbar: true }]
    .concat(mitBudget ? [{ schluessel: 'budget', titel: 'Budget', sortierbar: true, ausrichtung: 'rechts' }] : []);
  const zeilen = (L.zeilen || []).map(z => ({ zellen: { kampagne: { text: String(z.titel || ''), ziel: zuK(z.id) }, zeitraum: String(z.zeitraum || ''),
    status: { marke: { text: String(z.status_text || ''), ton: z.status === 'laufend' ? 'ok' : z.status === 'abgebrochen' ? 'warn' : 'grau' } }, talents: String(z.talents ?? ''),
    deliverables: z.d_ges ? z.d_erl + ' / ' + z.d_ges : '–', naechste: z.naechste_text ? { marke: { text: String(z.naechste_text), ton: z.ueberfaellig ? 'warn' : '' } } : '–',
    budget: String(z.budget_text || '–') } }));
  const tabelle = { typ: 'tabelle', id: 'alle', titel: 'Alle Kampagnen', spalten, zeilen, sortierung: L.sortierung || {}, seite: Number(L.seite) || 1, je_seite: 20, gesamt: Number(L.anzahl) || 0,
    leer: L.gesamt_sichtbar ? 'Keine Kampagnen für diesen Filter.' : 'Noch keine Kampagnen.' };
  const naechste = { typ: 'tabelle', id: 'naechste', titel: 'Nächste Deadlines', spalten: [{ schluessel: 'deadline', titel: 'Deadline' }, { schluessel: 'deliverable', titel: 'Deliverable' },
    { schluessel: 'talent', titel: 'Talent' }, { schluessel: 'kampagne', titel: 'Kampagne' }, { schluessel: 'status', titel: 'Status' }],
    zeilen: (L.naechste || []).map(x => ({ zellen: { deadline: { marke: { text: String(x.deadline_text || ''), ton: x.ueberfaellig ? 'warn' : '' } }, deliverable: String(x.name || ''), talent: String(x.talent || ''),
      kampagne: { text: String(x.kampagne || ''), ziel: zuK(x.kampagne_id, 'a-deliverables') }, status: String(x.status_text || '') } })),
    sortierung: {}, seite: 1, je_seite: 20, gesamt: (L.naechste || []).length, leer: 'Keine offenen Deadlines in den nächsten 14 Tagen.' };
  const freigaben = { typ: 'tabelle', id: 'freigaben', titel: 'Freigaben', spalten: [{ schluessel: 'eingereicht', titel: 'Eingereicht' }, { schluessel: 'deliverable', titel: 'Entwurf' },
    { schluessel: 'talent', titel: 'Talent' }, { schluessel: 'kampagne', titel: 'Kampagne' }, { schluessel: 'stand', titel: 'Stand' }],
    zeilen: (L.freigaben || []).map(x => ({ zellen: { eingereicht: String(x.eingereicht_text || ''), deliverable: { text: String(x.name || ''), ziel: zuK(x.kampagne_id, 'a-freigaben', { f: 'v-' + x.version_id }) },
      talent: String(x.talent || ''), kampagne: { text: String(x.kampagne || ''), ziel: zuK(x.kampagne_id) }, stand: { marke: { text: String(x.pruefung_text || ''), ton: '' } } } })),
    sortierung: {}, seite: 1, je_seite: 20, gesamt: (L.freigaben || []).length, leer: 'Keine Entwürfe warten auf Freigabe.' };
  const abschnitte = [
    { id: 'alle', titel: 'Alle Kampagnen', zahl: String(L.anzahl ?? 0), offen_standard: true, inhalt: [filter, tabelle] },
    { id: 'naechste', titel: 'Nächste Deadlines', zahl: String((L.naechste || []).length), offen_standard: true, inhalt: [naechste] },
    { id: 'freigaben', titel: 'Freigaben', zahl: String(KZ.freigaben_offen ?? 0), offen_standard: (KZ.freigaben_offen || 0) > 0, inhalt: [freigaben] }];
  const fenster = [];
  if (L.darf_anlegen) fenster.push({ id: 'neu', art: 'dialog', titel: 'Neue Kampagne', inhalt: [{ typ: 'formular', id: 'neu', aktion: 'tk_kampagne_neu', spalten: 2, felder: [
    { typ: 'text', name: 'marke', label: 'Marke', pflicht: true }, { typ: 'text', name: 'name', label: 'Kampagne', pflicht: true },
    { typ: 'datum', name: 'von', label: 'Beginn', pflicht: true }, { typ: 'datum', name: 'bis', label: 'Ende', pflicht: true },
  // Zuständige Person wählen nur mit „Talents verwalten“ (personen); Management ist selbst zuständig. Budget nur Admin und Management (Stefan 20.10.2026).
  ].concat(Array.isArray(L.personen) ? [{ typ: 'auswahl', name: 'zustaendig', label: 'Manager/in', wert: String(L.ich || ''), optionen: [{ wert: '', text: 'niemand' }].concat(L.personen.map(p => ({ wert: p.id, text: String(p.name || '') }))) }] : [])
  .concat(L.darf_budget === true ? [{ typ: 'text', name: 'budget', label: 'Budget', platzhalter: 'z. B. 18.000' }] : []).concat([
    { typ: 'mehrfach', name: 'talents', label: 'Talents', breite: 'voll', optionen: (L.talent_auswahl || []).map(t => ({ wert: String(t.id), text: String(t.anzeigename || '') })) },
    { typ: 'text', name: 'marken_konten', label: 'Marken-Accounts', platzhalter: '@marke', info: 'Zur Erkennung der Beiträge, mehrere mit Komma.' },
    { typ: 'text', name: 'hashtags', label: 'Hashtags', platzhalter: '#kampagne' },
    { typ: 'text', name: 'schlagwoerter', label: 'Schlagwörter', breite: 'voll' }]), knoepfe: knoepfe('Anlegen') }] });
  return aus({ seite, ueberblick, abschnitte, fenster });
}

// =====================================================================================================================
// Kampagne und Zuordnen: gemeinsame Daten
// =====================================================================================================================
const K = D.k || {};
if (K.ok !== true) return fehlt('Kampagne', K.fehler, true);
// geld: Budget dieser Kampagne (Admin, zuständiges Management); hon: Honorar-Spalte (Admin, Management; je Deliverable nur mit d.darf_honorar)
const k = K.kampagne || {}, kid = Number(k.kampagne_id), geld = K.geld === true, hon = K.honorar === true, planen = K.darf_planen === true;
const zuK = (anker, extra) => ({ seite: 'kampagnen', parameter: Object.assign({ kampagne: kid }, extra || {}), anker });
const linkZiel = (art, id) => ({ seite: 'link', parameter: { art, id } });
const titel = String(k.name || 'Kampagne');

if (D.ansicht === 'zuordnen') {
  const Z1 = D.z1 || {}, Z2 = D.z2 || {};
  if (Z1.ok !== true) return fehlt('Beiträge zuordnen', Z1.fehler, true);
  const beitraege = (Z1.beitraege || []).concat(Number(Z2.seite) === Number(Z1.seite) + 1 ? (Z2.beitraege || []) : []);
  const F = Z1.filter || {};
  const anz = Number(Z1.anzahl) || 0, s20 = Math.max(1, Math.ceil((Number(Z1.seite) || 1) / 2));
  const seite = { schluessel: 'kampagnen', art: 'funktion', titel: 'Beiträge zuordnen', beschreibung: String(k.marke || '') + ' · ' + titel + ' · ' + String(k.zeitraum_text || ''),
    krumen: krumen0.concat([{ text: titel, ziel: zuK() }, { text: 'Beiträge zuordnen' }]), zahnrad, hauptaktion: { text: 'Zur Kampagne', ziel: zuK('a-reporting') } };
  const filter = { typ: 'filter', id: 'zuordnen', label: 'Beiträge filtern', felder: [
    { typ: 'auswahl', name: 'talent', label: 'Talent', wert: String(F.talent || ''), optionen: (Z1.talent_auswahl || []).map(t => ({ wert: String(t.id), text: String(t.anzeigename || '') + ' (' + (t.anzahl_zugeordnet || 0) + ')' })) },
    { typ: 'auswahl', name: 'bereich', label: 'Beiträge', wert: String(F.bereich || 'zeitraum'), optionen: (Z1.bereich_auswahl || []).map(b => ({ wert: b.schluessel, text: String(b.name || '') })) }] };
  const tabelle = { typ: 'tabelle', id: 'zuordnen', titel: 'Beiträge', spalten: [{ schluessel: 'datum', titel: 'Datum' }, { schluessel: 'art', titel: 'Art' }, { schluessel: 'konto', titel: 'Account' },
    { schluessel: 'reichweite', titel: 'Reichweite', ausrichtung: 'rechts' }, { schluessel: 'zuordnung', titel: 'Zuordnung' }, { schluessel: 'aktion', titel: 'Aktion' }],
    zeilen: beitraege.map(b => ({ zellen: { datum: String(b.erstellt || ''), art: String(b.art_name || ''), konto: String(b.konto || b.plattform_name || ''),
      reichweite: String((b.reichweite || {}).text || '–'), zuordnung: b.zuordnung_text ? { marke: { text: String(b.zuordnung_text), ton: b.zuordnung === 'bestaetigt' ? 'ok' : 'grau' }, neben: String(b.grund || '') } : '',
      aktion: b.zuordnung === 'bestaetigt' ? { aktion: { text: 'Entfernen', aktion: 'tk_beitrag_entfernen', werte: { kampagne_id: kid, beitrag_id: b.id } } }
        : { aktion: { text: 'Zuordnen', aktion: 'tk_beitrag_zuordnen', werte: { kampagne_id: kid, beitrag_id: b.id } } } } })),
    sortierung: {}, seite: s20, je_seite: 20, gesamt: anz, leer: String(Z1.leer_text || 'Keine Beiträge.') };
  return aus({ seite, abschnitte: [{ id: 'zuordnen', titel: 'Beiträge', zahl: String(anz), offen_standard: true, inhalt: [filter, tabelle] }] });
}

// =====================================================================================================================
// Kampagne
// =====================================================================================================================
const KZ = K.kennzahlen || {}, ZI = K.ziele || {}, DL = K.deliverables || {}, ER = K.erinnerungen || {}, FR = K.freigaben || {}, RP = K.reporting || {};
const TAL = K.talents || [];
const beschr = [k.marke, k.zeitraum_text, geld && k.budget_text ? 'Budget ' + k.budget_text : '', k.zustaendig_name ? 'Manager/in: ' + k.zustaendig_name : '', k.abgebrochen ? 'abgebrochen' : '']
  .filter(Boolean).join(' · ');
const seite = { schluessel: 'kampagnen', art: 'funktion', titel, beschreibung: beschr, krumen: krumen0.concat([{ text: titel }]), zahnrad };
if (TAL.length && !k.abgebrochen) seite.hauptaktion = { text: 'Deliverable hinzufügen', fenster: 'deliverable-neu' };
const aktionen = [];
if (K.darf_bearbeiten) aktionen.push({ text: 'Kampagne bearbeiten', fenster: 'bearbeiten' });
if (planen) aktionen.push({ text: 'Planung und Ziele', fenster: 'planung' }, { text: 'Briefing bearbeiten', fenster: 'briefing' });
if (K.darf_zuordnen) aktionen.push({ text: 'Beiträge zuordnen', ziel: zuK(undefined, { ansicht: 'zuordnen' }) });
aktionen.push({ text: 'Kampagnenreport', ziel: { seite: 'talent-reports', parameter: { kampagne: kid, neu: 'kampagne' } } });
if (planen && !k.abgebrochen) aktionen.push({ text: 'Kampagne abbrechen', aktion: 'kp_abbrechen', werte: { kampagne_id: kid }, frage: titel + ' abbrechen? Erinnerungen werden angehalten.' });
if (planen && k.abgebrochen) aktionen.push({ text: 'Kampagne fortsetzen', aktion: 'kp_fortsetzen', werte: { kampagne_id: kid } });
if (K.darf_loeschen) aktionen.push({ text: 'Kampagne löschen', fenster: 'loeschen' });
seite.aktionen = aktionen;

// ---------- Überblick ----------
const ges = Number(KZ.gesamt) || 0, erl = Number(KZ.erledigt) || 0, NA = KZ.naechste || null;
const kennzahlen = [
  { label: 'Deliverables erledigt', wert: ges ? erl + ' / ' + ges : '–', neben: ges ? Math.round(erl * 100 / ges) + ' %' : '' },
  { label: 'Nächste Deadline', wert: NA ? String(NA.datum || '') : '–', neben: NA ? String(NA.neben || '') : '', ton: NA && NA.ueberfaellig ? 'warn' : '', ziel: zuK('a-deliverables') },
  { label: 'Reichweite bisher', wert: String(KZ.reichweite || '–'), neben: ZI.reichweite ? 'Ziel ' + ZI.reichweite.ziel : '', ziel: zuK('a-reporting') },
  geld ? { label: 'Budget verplant', wert: String(KZ.verplant_text || '–'), neben: k.budget_text ? 'von ' + k.budget_text : '' }
       : { label: 'Freigaben offen', wert: String(KZ.freigaben_offen ?? 0), neben: '', ziel: zuK('a-freigaben') }];
const offen = (K.offen || []).map(o => o.art === 'freigabe'
  ? { marke: { text: String(o.marke || ''), ton: '' }, text: String(o.text || ''), ziel: zuK('a-freigaben', { f: 'v-' + o.version_id }), ziel_text: 'Prüfen' }
  : { marke: { text: String(o.marke || ''), ton: o.warn ? 'warn' : '' }, text: String(o.text || ''), aktion: { text: 'Erinnern', aktion: 'kp_erinnern', werte: { id: o.deliverable_id } } });
const ziele = [];
if (ZI.reichweite) ziele.push({ text: 'Reichweite ' + ZI.reichweite.ziel, marke_hinten: true,
  marke: ZI.reichweite.prozent !== null && ZI.reichweite.prozent !== undefined ? { text: ZI.reichweite.prozent + ' %', ton: ZI.reichweite.prozent >= 100 ? 'ok' : '' } : { text: 'noch keine Daten', ton: 'grau' } });
if (ZI.interaktionsrate) ziele.push({ text: 'Interaktionsrate ab ' + ZI.interaktionsrate.ziel + ' %', marke_hinten: true,
  marke: ZI.interaktionsrate.ist ? { text: ZI.interaktionsrate.ist + ' %', ton: ZI.interaktionsrate.erreicht ? 'ok' : '' } : { text: 'noch keine Daten', ton: 'grau' } });
if (ZI.link_klicks) ziele.push({ text: 'Link-Klicks ' + ZI.link_klicks.ziel, marke_hinten: true,
  marke: ZI.link_klicks.ist ? { text: ZI.link_klicks.ist + (ZI.link_klicks.prozent !== null && ZI.link_klicks.prozent !== undefined ? ' (' + ZI.link_klicks.prozent + ' %)' : ''), ton: '' } : { text: 'noch keine Daten', ton: 'grau' } });
const ueberblick = { kennzahlen, karten: [{ titel: 'Offen', leer: 'Nichts offen.', eintraege: offen },
  { titel: 'Ziele', leer: 'Keine Ziele festgelegt.', eintraege: ziele }] };

// ---------- Briefing ----------
const LI = K.links || [];
const paare = [['Ziel', k.briefing_ziel], ['Kernbotschaft', k.kernbotschaft], ['Dos', k.dos], ["Don'ts", k.donts], ['Kennzeichnung als Werbung', k.werbekennzeichnung],
  ['Marken-Accounts', (k.marken_konten || []).map(x => '@' + x).join(', ')], ['Hashtags', (k.hashtags || []).map(x => /^#/.test(String(x)) ? String(x) : '#' + x).join(', ')], ['Schlagwörter', (k.schlagwoerter || []).join(', ')]]
  .filter(p => p[1]).map(p => ({ label: p[0], wert: String(p[1]) }));
const briefing = [];
if (paare.length) briefing.push({ typ: 'paare', eintraege: paare }); else briefing.push({ typ: 'text', ton: 'grau', text: 'Noch kein Briefing.' });
briefing.push({ typ: 'unterueberschrift', text: 'Dateien der Marke', info: 'Nur Links zum Cloud-Dienst; Ally speichert keine Dateien.' },
  { typ: 'liste', leer: 'Keine Links.', eintraege: LI.map(l => Object.assign({ fett: String(l.titel || ''), text: String(l.dienst_text || ''), ziel: linkZiel('kl', l.id), ziel_text: 'Öffnen' },
    planen ? { aktion: { text: 'Entfernen', aktion: 'kp_link_loeschen', werte: { id: l.id }, frage: 'Link „' + String(l.titel || '') + '“ entfernen?' } } : {})) });
if (planen) briefing.push({ typ: 'aktion', text: 'Briefing bearbeiten', fenster: 'briefing' }, { typ: 'aktion', text: 'Link hinzufügen', fenster: 'link-neu' });

// ---------- Talents und Deliverables ----------
const DZ = DL.zeilen || [];
const dSpalten = [{ schluessel: 'talent', titel: 'Talent', sortierbar: true }, { schluessel: 'plattform', titel: 'Plattform', sortierbar: true },
  { schluessel: 'format', titel: 'Format', sortierbar: true }, { schluessel: 'deadline', titel: 'Deadline', sortierbar: true },
