// ---------- Zeitplan (Kalenderwochen, bei langen Kampagnen Monate) ----------
const tag = s => { const m = /^(\d{4})-(\d{2})-(\d{2})$/.exec(String(s || '')); return m ? Date.UTC(+m[1], +m[2] - 1, +m[3]) / 864e5 : null; };
const ZP = K.zeitplan || [];
const tage = [tag(k.von_iso), tag(k.bis_iso)].concat(ZP.map(z => tag(z.deadline)), ZP.map(z => tag(z.veroeffentlichen))).filter(x => x !== null);
const zeitplan = [];
if (ZP.length && tage.length) {
  const vonT = Math.min(...tage), bisT = Math.max(...tage) + 1;
  const wtag = t => (new Date(t * 864e5).getUTCDay() + 6) % 7;
  const start = vonT - wtag(vonT), wochen = Math.ceil((bisT - start) / 7);
  const kw = t => { const d = new Date(t * 864e5); d.setUTCDate(d.getUTCDate() + 3 - (d.getUTCDay() + 6) % 7); const j = new Date(Date.UTC(d.getUTCFullYear(), 0, 4));
    return 1 + Math.round(((d - j) / 864e5 - 3 + (j.getUTCDay() + 6) % 7) / 7); };
  let spalten, pos;
  if (wochen <= 26) {
    spalten = Array.from({ length: wochen }, (_, i) => 'KW ' + kw(start + i * 7));
    pos = t => (t - start) / 7;
  } else {
    const d0 = new Date(vonT * 864e5), m0 = d0.getUTCFullYear() * 12 + d0.getUTCMonth(), d1 = new Date((bisT - 1) * 864e5), m1 = d1.getUTCFullYear() * 12 + d1.getUTCMonth();
    spalten = Array.from({ length: m1 - m0 + 1 }, (_, i) => String((m0 + i) % 12 + 1).padStart(2, '0') + '/' + Math.floor((m0 + i) / 12));
    pos = t => { const d = new Date(t * 864e5), m = d.getUTCFullYear() * 12 + d.getUTCMonth(); const tim = new Date(Date.UTC(d.getUTCFullYear(), d.getUTCMonth() + 1, 0)).getUTCDate();
      return (m - m0) + (d.getUTCDate() - 1) / tim; };
  }
  const zeilen = [];
  for (const z of ZP) {
    let r = zeilen.find(x => x.id === z.talent_id);
    if (!r) { r = { id: z.talent_id, name: String(z.talent || ''), balken: [] }; zeilen.push(r); }
    const a = tag(z.deadline), b = (tag(z.veroeffentlichen) ?? a) + 1;
    r.balken.push({ text: String(z.format_text || ''), von: Math.max(0, pos(a)), bis: Math.max(pos(a) + 0.4, pos(b)), ton: z.ueberfaellig ? 'warn' : '' });
  }
  zeitplan.push({ typ: 'grafik', art: 'zeitplan', erste_spalte: 'Talent', spalten, zeilen: zeilen.map(r => ({ name: r.name, balken: r.balken })),
    beschreibung: 'Zeitplan der Deliverables je Talent von der Deadline bis zur Veröffentlichung' });
} else zeitplan.push({ typ: 'text', ton: 'grau', text: 'Noch keine Deliverables im Zeitplan.' });
const zpZahl = (() => { const s = (zeitplan[0] || {}).spalten || []; return s.length ? s[0] + (s.length > 1 ? '–' + String(s[s.length - 1]).replace(/^KW /, '') : '') : ''; })();

