    { typ: 'text', name: 'ziel_reichweite', label: 'Ziel Reichweite', wert: k.ziel_reichweite === null || k.ziel_reichweite === undefined ? '' : String(k.ziel_reichweite) },
    { typ: 'text', name: 'ziel_interaktionsrate', label: 'Ziel Interaktionsrate (%)', wert: k.ziel_interaktionsrate === null || k.ziel_interaktionsrate === undefined ? '' : String(k.ziel_interaktionsrate).replace('.', ',') },
    { typ: 'text', name: 'ziel_link_klicks', label: 'Ziel Link-Klicks', wert: k.ziel_link_klicks === null || k.ziel_link_klicks === undefined ? '' : String(k.ziel_link_klicks) },
    { typ: 'text', name: 'link_klicks', label: 'Link-Klicks bisher', wert: k.link_klicks === null || k.link_klicks === undefined ? '' : String(k.link_klicks), info: 'Von Hand, z. B. aus dem Tracking der Marke.' },
    { typ: 'haken', name: 'erinnerungen_an', label: 'Erinnerungen für diese Kampagne', an: k.erinnerungen_an !== false, breite: 'voll' }]), knoepfe: knoepfe() }] });
  fenster.push({ id: 'briefing', art: 'dialog', titel: 'Briefing', inhalt: [{ typ: 'formular', id: 'briefing', aktion: 'kp_briefing', werte: { kampagne_id: kid }, felder: [
    { typ: 'textbereich', name: 'briefing_ziel', label: 'Ziel', zeilen: 2, wert: String(k.briefing_ziel || '') }, { typ: 'textbereich', name: 'kernbotschaft', label: 'Kernbotschaft', zeilen: 2, wert: String(k.kernbotschaft || '') },
    { typ: 'textbereich', name: 'dos', label: 'Dos', zeilen: 3, wert: String(k.dos || '') }, { typ: 'textbereich', name: 'donts', label: "Don'ts", zeilen: 3, wert: String(k.donts || '') },
    { typ: 'text', name: 'werbekennzeichnung', label: 'Kennzeichnung als Werbung', wert: String(k.werbekennzeichnung || ''), platzhalter: 'z. B. Anzeige' }], knoepfe: knoepfe() }] });
  fenster.push({ id: 'link-neu', art: 'dialog', titel: 'Link hinzufügen', inhalt: [{ typ: 'formular', id: 'link-neu', aktion: 'kp_link_neu', werte: { kampagne_id: kid }, felder: [
    { typ: 'text', name: 'titel', label: 'Titel', pflicht: true }, { typ: 'text', name: 'link', label: 'Link', pflicht: true, platzhalter: 'https://', info: 'Link zum Cloud-Dienst, z. B. Google Drive.' }],
    knoepfe: knoepfe('Hinzufügen') }] });
  const regelFelder = r => [
    { typ: 'auswahl', name: 'wann', label: 'Wann', wert: !r ? 'vorher' : r.versatz_tage < 0 ? 'vorher' : r.versatz_tage > 0 ? 'danach' : 'am_tag', optionen: [{ wert: 'vorher', text: 'vorher' }, { wert: 'am_tag', text: 'am Tag' }, { wert: 'danach', text: 'überfällig' }] },
    { typ: 'zahl', name: 'tage', label: 'Tage', wert: r ? String(Math.abs(r.versatz_tage) || 1) : '3', min: 1, max: 30 },
    { typ: 'auswahl', name: 'bezug', label: 'Bezug', wert: r ? r.bezug : 'deadline', optionen: [{ wert: 'deadline', text: 'Deadline' }, { wert: 'veroeffentlichung', text: 'Veröffentlichung' }] },
    { typ: 'auswahl', name: 'empfaenger', label: 'An', wert: r ? r.empfaenger : 'talent', optionen: [{ wert: 'talent', text: 'das Talent' }, { wert: 'zustaendig', text: 'Manager/in' }] },
    { typ: 'mehrfach', name: 'kanaele', label: 'Wege zum Talent', wert: r ? (r.kanaele || []).filter(x => x !== 'glocke') : ['bereich'], breite: 'voll',
      optionen: [{ wert: 'bereich', text: 'Talent-Bereich' }, { wert: 'kalender', text: 'Kalender des Talents' }, { wert: 'mail', text: 'Mail' }], info: 'Der Manager oder die Managerin bekommt eine Benachrichtigung.' },
    { typ: 'zeit', name: 'uhrzeit', label: 'Uhrzeit', wert: r ? String(r.uhrzeit || '09:00') : '09:00' }];
  fenster.push({ id: 'regel-neu', art: 'dialog', titel: 'Regel hinzufügen', inhalt: [{ typ: 'formular', id: 'regel-neu', aktion: 'kp_regel_neu', werte: { kampagne_id: kid }, spalten: 2,
    felder: regelFelder(null), knoepfe: knoepfe('Hinzufügen') }] });
  for (const r of RG) if (!r.standard) fenster.push({ id: 'r-' + r.id, art: 'dialog', titel: 'Regel bearbeiten', schliessen_ziel: zuK('a-erinnerungen'), inhalt: [
    { typ: 'formular', id: 'regel-' + r.id, aktion: 'kp_regel_aendern', werte: { id: r.id, aktiv_sichtbar: '1' }, spalten: 2,
      felder: regelFelder(r).concat([{ typ: 'haken', name: 'aktiv', label: 'Aktiv', an: r.aktiv === true, breite: 'voll' }]), knoepfe: knoepfe() },
    { typ: 'aktion', text: 'Regel löschen', aktion: 'kp_regel_loeschen', werte: { id: r.id }, frage: 'Regel „' + String(r.text || '') + '“ löschen?' }] });
}
if (K.darf_loeschen) fenster.push({ id: 'loeschen', art: 'dialog', titel: 'Kampagne löschen', inhalt: [{ typ: 'text', ton: 'warn', text: 'Löscht Deliverables, Entwürfe, Aufgaben und Erinnerungen dieser Kampagne. Beiträge und Zahlen der Talents bleiben.' },
  { typ: 'formular', id: 'loeschen', aktion: 'tk_kampagne_loeschen', werte: { id: kid }, felder: [{ typ: 'text', name: 'bestaetigung', label: 'Name der Kampagne zur Bestätigung', pflicht: true, platzhalter: String(k.loeschen_bestaetigung || '') }],
    knoepfe: knoepfe('Endgültig löschen') }] });

return aus({ seite, ueberblick, abschnitte, fenster });

// Parameter (ALLY 26, Kampagnen, BA6): Sitzung, Ansicht (liste | kampagne | zuordnen) aus ?kampagne=<id>&ansicht=zuordnen, Filter der Liste (status, suche, talent),
// Filter beim Zuordnen (talent, bereich), Seiten der Tabellen (?p=<tabelle>:<n>). Die Sortierung je Tabelle liest „Daten laden“ aus dem Zustand der Person.
const E = $input.first().json;
const P = E.parameter || {};
const S = E.seiten || {};
const id = /^[0-9]{1,9}$/.test(String(P.kampagne || '')) ? String(P.kampagne) : '';
const ansicht = id ? (P.ansicht === 'zuordnen' ? 'zuordnen' : 'kampagne') : 'liste';
const n = v => Math.min(9999, Math.max(1, Number(v) || 1));
const f = {};
if (ansicht === 'liste') {
  if (['laufend', 'geplant', 'beendet', 'abgebrochen'].includes(String(P.status || ''))) f.status = String(P.status);
  if (P.suche) f.suche = String(P.suche).slice(0, 100);
  if (/^[0-9]{1,9}$/.test(String(P.talent || ''))) f.talent = String(P.talent);
  f.seite = String(n(S.alle));
} else if (ansicht === 'kampagne') {
  f.dseite = String(n(S.deliverables)); f.fseite = String(n(S.freigaben)); f.vseite = String(n(S.vorschlaege)); f.bseite = String(n(S.beitraege));
} else {
  if (/^[0-9]{1,9}$/.test(String(P.talent || ''))) f.talent = String(P.talent);
  f.bereich = P.bereich === 'alle' ? 'alle' : 'zeitraum';
}
// Zuordnen: 20 je Seite aus zwei Datenbankseiten zu je 10
const zs = n(S.zuordnen);
return [{ json: { ansicht, werte: [/^[0-9a-f]{64}$/.test(String(E.sitzung || '')) ? String(E.sitzung) : '', ansicht, id, JSON.stringify(f), String(zs * 2 - 1), String(zs * 2)] } }];

// Punkt 5l (Stefan 21.10.2026): Kampagnen-Vorschläge wie in ALLY 8 auch ablehnen („Entfernen“ = tk_beitrag_entfernen, Status „entfernt“, Ally schlägt den Beitrag nicht noch einmal vor).
// Ergänzt in den Tabellen „Vorschläge“ (Reporting) und „Beiträge zuordnen“ (nur Zeilen mit Zuordnung „vorschlag“) die Zelle Aktion um aktionen = [Zuordnen, Entfernen].
// aktion bleibt als Rückfall für Baukästen ohne „aktionen“. Rechte prüft die Datenbank wie bei „Zuordnen“ (gleiche Bedingung: Aktion nur, wenn Zuordnen angeboten wird).
const D = $('Daten laden').first().json || {};
const VOR = new Set([].concat((D.z1 || {}).beitraege || [], (D.z2 || {}).beitraege || []).filter(b => b && b.zuordnung === 'vorschlag').map(b => String(b.id)));
const FRAGE = 'Vorschlag entfernen? Der Beitrag wird dieser Kampagne nicht zugeordnet.';
const ergaenze = (tab, nurVorschlag) => {
  for (const z of (tab.zeilen || [])) {
    const c = z && z.zellen && z.zellen.aktion, a = c && typeof c === 'object' ? c.aktion : null;
    if (!a || !['tk_beitrag_bestaetigen', 'tk_beitrag_zuordnen'].includes(a.aktion) || !a.werte || Array.isArray(c.aktionen)) continue;
    if (nurVorschlag && !VOR.has(String(a.werte.beitrag_id))) continue;
    c.aktionen = [a, { text: 'Entfernen', aktion: 'tk_beitrag_entfernen', werte: { kampagne_id: a.werte.kampagne_id, beitrag_id: a.werte.beitrag_id }, frage: FRAGE }];
  }
};
const aus = $input.all().map(it => {
  const I = it.json && it.json.inhalt;
  for (const ab of ((I && I.abschnitte) || [])) for (const b of (ab.inhalt || [])) {
    if (b && b.typ === 'tabelle' && b.id === 'vorschlaege') ergaenze(b, false);
    if (b && b.typ === 'tabelle' && b.id === 'zuordnen') ergaenze(b, true);
  }
  return it;
});
return aus;

// Links in neuem Tab (ALLY 26, Abnahme-Korrektur, Stefan 21.10.2026): Links der Kampagnen (geprüfte Seite „link“: Dateien der Marke kl, Entwürfe v, veröffentlichte Beiträge d) öffnen in einem neuen Tab
// und tragen den Pfeil für fremde Seiten. Der Baukasten (ALLY 21) zeichnet das für Ziele mit neuer_tab. Sonst bleibt alles unverändert.
const ARTEN = ['kl', 'v', 'd'];
const markiere = x => {
  if (Array.isArray(x)) { x.forEach(markiere); return; }
  if (!x || typeof x !== 'object') return;
  for (const k of Object.keys(x)) {
    const v = x[k];
    if (v && typeof v === 'object' && !Array.isArray(v) && v.seite === 'link' && v.parameter && ARTEN.includes(String(v.parameter.art || ''))) v.neuer_tab = true;
    else markiere(v);
  }
};
const aus = $input.all().map(x => x.json);
for (const j of aus) if (j && j.inhalt) markiere(j.inhalt);
return aus.map(json => ({ json }));

