-- Testdaten-Kennung (ALLY 26, Migration 79, Stefan 21.10.2026): welche Talents, Kampagnen und Personen Testdaten sind und ob die Person sie ausgeblendet hat.
-- Ohne Testdaten nur {aktiv: false}. $1 Sitzung.
SELECT ally_testdaten_kennung($1::text) AS td;

parameters.jsCode:
// Testdaten kennzeichnen (ALLY 26, Migration 79, Stefan 21.10.2026): Seite aus „Links in neuem Tab“, Kennung aus „Testdaten-Kennung“ (ally_testdaten_kennung).
const aus = $('Links in neuem Tab').all().map(x => x.json);
let TD = {};
try { TD = ($input.first().json || {}).td || {}; } catch (e) { TD = {}; }
if (!TD || typeof TD !== 'object' || TD.aktiv !== true) return aus.map(json => ({ json }));
const KID = String((($('Parameter').first().json || {}).werte || [])[2] || '');
const SEITE_TEST = KID !== '' && (Array.isArray(TD.kampagnen) ? TD.kampagnen : []).map(String).includes(KID);
// ---- gemeinsamer Teil „Testdaten kennzeichnen“ (Migration 79, Stefan 21.10.2026): kleine Marke „Testdaten“ an Einträgen, die zu einem Test-Talent oder einer
// Test-Kampagne führen; hat die Person „Testdaten ausblenden“ gewählt, fallen diese Zeilen und Einträge weg (Zähler der Tabelle entsprechend kleiner).
// Ist die Seite selbst ein Test-Talent bzw. eine Test-Kampagne, steht die Marke in der Zeile unter dem Titel. Dazu unter „Aktionen“ „Testdaten ausblenden/einblenden“
// (td_ausblenden, je Person gespeichert) und ein Hinweis am Titel. Ohne Testdaten unverändert.
const MARKE = { text: 'Testdaten', ton: 'grau' };
const T = new Set((Array.isArray(TD.talents) ? TD.talents : []).map(String));
const K = new Set((Array.isArray(TD.kampagnen) ? TD.kampagnen : []).map(String));
const raus = TD.ausblenden === true && TD.selbst_test !== true && !SEITE_TEST;
const istTest = z => { if (!z || typeof z !== 'object' || !z.parameter || typeof z.parameter !== 'object') return false;
  if (z.seite === 'talent') return T.has(String(z.parameter.id));
  if (z.seite === 'kampagne') return K.has(String(z.parameter.id));
  if (z.seite === 'kampagnen') return z.parameter.kampagne !== undefined && K.has(String(z.parameter.kampagne));
  return false; };
const zeileTest = r => !!(r && r.zellen && typeof r.zellen === 'object' && Object.values(r.zellen).some(c => c && typeof c === 'object' && istTest(c.ziel)));
const geh = x => {
  if (Array.isArray(x)) { x.forEach(geh); return; }
  if (!x || typeof x !== 'object') return;
  if (raus && Array.isArray(x.zeilen) && x.zeilen.some(zeileTest)) {
    const vor = x.zeilen.length; x.zeilen = x.zeilen.filter(r => !zeileTest(r));
    if (typeof x.gesamt === 'number') x.gesamt = Math.max(x.zeilen.length, x.gesamt - (vor - x.zeilen.length));
  }
  if (raus && Array.isArray(x.eintraege)) x.eintraege = x.eintraege.filter(e => !(e && typeof e === 'object' && istTest(e.ziel)));
  if (raus && Array.isArray(x.karten)) x.karten = x.karten.filter(k => !(k && typeof k === 'object' && (istTest(k.titel_ziel) || istTest(k.ziel))));
  if (x.zellen && typeof x.zellen === 'object') {
    for (const c of Object.values(x.zellen)) if (c && typeof c === 'object' && istTest(c.ziel) && !c.marke) c.marke = MARKE;
  } else if (x.titel_ziel && istTest(x.titel_ziel)) {
    if (!x.art) x.art = 'Testdaten'; else if (!/Testdaten/.test(String(x.art))) x.art = String(x.art) + ' · Testdaten';
  } else if (typeof x.text === 'string' && istTest(x.ziel) && x.typ === undefined && !x.aktion && !(x.marke && x.marke.text === 'Testdaten')) {
    if (!x.marke) { x.marke = MARKE; x.marke_hinten = true; } else if (!/Testdaten/.test(x.text)) x.text = x.text + ' (Testdaten)';
  }
  for (const k of Object.keys(x)) if (x[k] && typeof x[k] === 'object') geh(x[k]);
};
for (const j of aus) {
  if (!j || !j.inhalt) continue;
  // Seite eines Test-Talents bzw. einer Test-Kampagne: nur die Marke unter dem Titel (alles darauf gehört dazu)
  if (!SEITE_TEST) { geh(j.inhalt.abschnitte); geh(j.inhalt.bloecke); geh(j.inhalt.ueberblick); geh(j.inhalt.fenster); }
  const S = j.inhalt.seite;
  if (!S || typeof S !== 'object') continue;
  if (SEITE_TEST) S.meta = Object.assign({}, S.meta && typeof S.meta === 'object' ? S.meta : {}, { marke: MARKE });
  if (TD.selbst_test !== true) {
    S.aktionen = (Array.isArray(S.aktionen) ? S.aktionen : []).concat([{ text: TD.ausblenden === true ? 'Testdaten einblenden' : 'Testdaten ausblenden', aktion: 'td_ausblenden',
      werte: { aus: TD.ausblenden === true ? '0' : '1' } }]);
    S.info = [].concat(S.info === undefined || S.info === null || S.info === '' ? [] : S.info,
      [TD.ausblenden === true ? 'Testdaten sind für dich ausgeblendet (unter „Aktionen“ wieder einblenden). Summen und Kennzahlen aus allen Daten enthalten sie weiter.'
        : 'Einträge mit „Testdaten“ sind Beispieldaten zum Ausprobieren. Summen und Kennzahlen enthalten sie. Unter „Aktionen“ lassen sie sich für dich ausblenden.']);
  }
}
return aus.map(json => ({ json }));

// Kampagnen mit Papierkorb (ALLY 26, Migration 131, E13 „Löschen = Papierkorb“, Stefan 23.10.2026; Plan freigegeben vom Koordinator).
// Ergänzt die Seite Kampagnen, ohne die Knoten davor zu ändern (Muster wie „Vorlagen (Papierkorb)“, Migration 132):
//   Liste: Knopf „Papierkorb“ im Kopf ohne Zähler (E9). Unterseite papierkorb=1: Kampagnen, Deliverables, Links und eigene Erinnerungen im Papierkorb
//   mit „Wiederherstellen“ und „Endgültig löschen“, oben „Papierkorb leeren“ (genau die angezeigten, höchstens 1000); 10 je Seite (E8); nur der Papierkorb (ohne Überblick).
//   Kampagne: „Kampagne löschen“ (Fenster mit Eingabe des Namens) wird „In den Papierkorb“ mit milder Rückfrage (E13); Deliverable, Link und Regel ebenso;
//   „Standard-Erinnerungen verwenden“ sagt, dass die eigenen Regeln in den Papierkorb kommen.
// Die Daten liefert die Datenbank (talents_kampagnen_ui.papierkorb: nur Einträge mit Recht, Umfang und Anzahlen genau aus dem Schnappschuss);
// die Aktionen prüfen die Rechte selbst (talents_kampagnen_papierkorb).
const E = $('Start').first().json;
const D = $('Daten laden').first().json || {};
const P = E.parameter || {};
const LI = x => Array.isArray(x) ? x : [];
const s0 = v => String(v ?? '');
const JE = 10;
const MAX = 1000;
const LEER = 'Das lässt sich nicht rückgängig machen.';
const BLEIBT = 'Beiträge und Zahlen der Talents bleiben erhalten.';
const blatt = (tab, n) => { const s = Math.max(1, Number((E.seiten || {})[tab]) || 1); return Math.min(s, Math.max(1, Math.ceil(n / JE))); };
const geh = (x, f) => { if (Array.isArray(x)) { x.forEach(y => geh(y, f)); return; } if (!x || typeof x !== 'object') return; f(x); for (const k of Object.keys(x)) geh(x[k], f); };
const name = v => v.art === 'kampagne' ? 'Kampagne „' + s0(v.titel) + '“' : v.art === 'deliverable' ? s0(v.titel) : v.art === 'link' ? 'Link „' + s0(v.titel) + '“' : 'Erinnerung „' + s0(v.titel) + '“';
const mit = v => Number(v.mit) > 0 ? (Number(v.mit) === 1 ? '1 weiterer Eintrag dieser Kampagne im Papierkorb' : Number(v.mit) + ' weitere Einträge dieser Kampagne im Papierkorb') : '';

return $input.all().map(it => {
  const j = it.json || {};
  const I = j.inhalt;
  if (!I || typeof I !== 'object' || !I.seite || D.ok !== true) return it;
  const seite = I.seite;
  const L = D.l && typeof D.l === 'object' ? D.l : null;
  if (D.ansicht === 'liste') {
    const PK = L && L.ok === true && L.papierkorb && Array.isArray(L.papierkorb.eintraege) ? L.papierkorb.eintraege : null;
    if (!PK) return it;
    if (s0(P.papierkorb) !== '1') {
      seite.knoepfe = LI(seite.knoepfe).filter(k => !(k && k.text === 'Papierkorb')).concat([{ text: 'Papierkorb', ziel: { seite: 'kampagnen', parameter: { papierkorb: '1' } } }]);
      return { json: j };
    }
    seite.titel = 'Papierkorb';
    seite.krumen = [{ text: 'Startseite', ziel: { seite: 'start' } }, { text: 'Kampagnen', ziel: { seite: 'kampagnen' } }, { text: 'Papierkorb' }];
    seite.beschreibung = 'Kampagnen, Deliverables, Links und eigene Erinnerungen im Papierkorb. Ally erinnert dafür nicht. Wiederherstellen bringt alles zurück, was mit ihnen in den Papierkorb kam.';
    delete seite.hauptaktion; delete seite.aktionen; delete seite.formular; delete seite.speichern; delete seite.knoepfe;
    const n = Math.min(PK.length, MAX), alle = Number(L.papierkorb.leeren_anzahl) || PK.length;
    if (n) seite.hauptaktion = { text: 'Papierkorb leeren', art: 'neben', aktion: 'kp_papierkorb_leeren', werte: { ids: PK.slice(0, MAX).map(v => s0(v.id)).join(','), anzahl: String(n) },
      frage: 'Papierkorb endgültig leeren? ' + (PK.length > MAX ? 'Die neuesten ' + MAX + ' der ' + PK.length + ' Einträge im Papierkorb werden endgültig gelöscht, dazu, was mit ihren Kampagnen im Papierkorb liegt.'
        : alle === 1 ? name(PK[0]) + ' wird endgültig gelöscht.' : 'Alle ' + alle + ' Einträge im Papierkorb werden endgültig gelöscht.') + ' ' + BLEIBT + ' ' + LEER };
    const bl = blatt('kampagnen-papierkorb', PK.length);
